def _is_within(path: str, scope: str) -> bool:
    if "://" in path or "://" in scope:
        return path == scope or path.startswith(scope.rstrip("/") + "/")
    try:
        return os.path.commonpath([path, scope]) == scope
    except ValueError:
        return False

