                return lock
        order = ["pubspec.lock", "package-lock.json", "uv.lock", "poetry.lock", "Cargo.lock", "go.sum", "pnpm-lock.yaml", "yarn.lock"]
        return next((lock for lock in order if lock in lockfiles), lockfiles[0])

