def select_joint_context(payload: dict, snapshot: dict, retrieval: dict, *, max_tokens: int):
    """Close admitted seed units, not maximize a count of arbitrary paragraphs.

    First prefer closure of incomplete seed atoms and explicit ancestor subject
    introductions; then the cheapest feasible packet at that gain. Only when
    neither improvement exists consider a containing-section fallback. These are
    structural preferences, NOT an oracle of semantic answer completeness.
    """
    # This experiment addresses direct questions only. Explicit host lookups
    # carry a separate recovery/coverage contract; keep that producer unchanged.
    plan = retrieval.get("documentation_query_plan") or {}
    if any(q.get("origin") == "host_lookup" for q in plan.get("queries") or () if isinstance(q, dict)):
        return payload, snapshot
    closures = {}
    for row in payload.get("sources") or ():
        source = (snapshot.get(row.get("evidence_id")) or {}).get("source")
        if not isinstance(source, dict):
            continue
        options, _ = source_options(row, source)
        for alt, _, kind in options:
            if kind == "complete_atom":
                closures[row["evidence_id"]] = alt["snippet"]
    candidates = []
    for p, b, r, kinds, intro in packet_alternatives(payload, snapshot, retrieval, max_tokens=max_tokens):
        by_id = {s["evidence_id"]: s["snippet"] for s in p["sources"]}
        mapping = retained_seed_mapping(payload, snapshot, p, b)
        closed = sum(text in by_id.get(mapping.get(eid, ""), "") for eid, text in closures.items())
        coalesced = len(mapping) - len(set(mapping.values()))
        gain = (closed, coalesced, int(intro))
        fallback = any(k in {"containing_section", "seed_envelope"} for k in kinds)
        if gain != (0, 0, 0) or fallback:
            candidates.append((gain, docs_context_budget_tokens(p), p, b, r, kinds, fallback))
    useful = [c for c in candidates if c[0] != (0, 0, 0)]
    if useful:
        best_gain = max(c[0] for c in useful)
        viable = [c for c in useful if c[0] == best_gain]
    else:
        viable = [c for c in candidates if c[6]]
    if not viable:
        return payload, snapshot
    chosen = min(viable, key=lambda c: (c[1], c[5]))
    _, cost, result, bindings, r, kinds, _ = chosen
    mapping = retained_seed_mapping(payload, snapshot, result, bindings)
    retrieval.clear()
    retrieval.update(r)
    retrieval.setdefault("retrieval_diagnostics", {}).se

def seed_envelopes(payload: dict, snapshot: dict) -> list[tuple[int, tuple]]:
    groups: dict[tuple, list] = {}
    for index, row in enumerate(payload.get("sources", [])):
        source = (snapshot.get(row.get("evidence_id")) or {}).get("source")
        if not isinstance(source, dict):
            continue
        raw = _verified_document(source, row)
        if raw is None:
            continue
        ref = source["_reference_evidence"]
        start = raw.find(row["snippet"], ref["char_start"], ref["char_end"])
        end = start + len(row["snippet"])
        parents = parse_markdown_parents(raw, ref["source"]["document_id"])
        if len(parents) > MAX_PARENT_SECTIONS:
            continue
        owner = next((p for p in parents if p.char_start <= start < end <= p.char_end), None)
        if owner is None:
            continue
        key = (row["project_identity"], row["path_or_url"], source.get("_source_snapshot_sha256"),
               source.get("_source_catalog_hash"), source.get("resolved_version"), owner.logical_id)
        groups.setdefault(key, []).append((index, row, source, raw, owner, start, end))
    result = []
    for rows in groups.values():
        if len(rows) < 2:
            continue
        index, row, source, raw, owner, _, _ = rows[0]
        if any(item[3] != raw for item in rows):
            continue
        atoms = [a for a in structural_spans(raw, owner.char_start, owner.char_end) if a[2] != "whitespace"]
        left, right = min(item[5] for item in rows), max(item[6] for item in rows)
        hits = [i for i, (a, z, _) in enumerate(atoms) if a < right and left < z]
        if not hits:
            continue
        start, end = min(left, atoms[hits[0]][0]), max(right, atoms[hits[-1]][1])
        bounds = [(start, end)]
        if hits[0] > 0 and atoms[hits[0] - 1][2] == "prose":
            bounds.append((atoms[hits[0] - 1][0], end))
        seen = {row["snippet"]}
        for a, z in bounds:
            proposal = _context_row(source, row, raw, owner, a, z, supplementary=False)
            if proposal is not None and proposal[0]["snippet"] not in seen:
                seen.add(proposal[0]["snippet"])
                result.append((index, (*proposal, "seed_envelope")))
    return result

def _result_reason_code(result: RefreshResult, status: str) -> str:
        if status == "succeeded":
            return "healthy"
        if status == "partial":
            network_codes = {"connect_timeout", "read_timeout", "dns_failure", "tls_failure", "network_unreachable", "http_failure"}
            if code := next((code for code in result.reason_codes if code in network_codes), None):
                return code
            return "partial_failure"
        if result.status == "needs_docs_url":
            return "needs_docs_url"
        return str(result.reason_codes[0] if result.reason_codes else (result.preindex or {}).get("reason_code") or "indexing_failed")

def _retryable_reason_code(reason_code: str) -> bool:
        return reason_code in {
            "connect_timeout", "read_timeout", "dns_failure", "tls_failure", "network_timeout",
            "network_unreachable", "network_transport_error", "job_deadline_exceeded", "vector_indexing_failed",
        }

