def merged_discovery_diagnostics(items: list[dict[str, Any]]) -> dict[str, Any]:
    if not items:
        return {
            "discovery_strategy": "unknown", "sitemap_pages": 0, "seed_pages": 0,
            "fallback_pages": 0, "warnings": [], "page_ledger": [],
            "page_failure_count": 0, "page_failure_summary": [],
        }
    strategies: list[str] = []
    fallback_reasons: list[str] = []
    page_ledger: list[dict[str, Any]] = []
    sitemap_pages = seed_pages = fallback_pages = 0
    for item in items:
        strategy = item.get("discovery_strategy")
        if strategy and str(strategy) not in strategies:
            strategies.append(str(strategy))
        sitemap_pages += int(item.get("sitemap_pages") or 0)
        seed_pages += int(item.get("seed_pages") or 0)
        fallback_pages += int(item.get("fallback_pages") or 0)
        reason = item.get("fallback_reason")
        if reason and str(reason) not in fallback_reasons:
            fallback_reasons.append(str(reason))
        page_ledger.extend(dict(page) for page in item.get("page_ledger") or [] if isinstance(page, dict))
    failed = [page for page in page_ledger if page.get("outcome") in {"failed", "skipped"}]
    return {
        "discovery_strategy": "+".join(strategies) if strategies else "unknown",
        "sitemap_pages": sitemap_pages,
        "seed_pages": seed_pages,
        "fallback_pages": fallback_pages,
        "warnings": [{"code": reason, "blocking": False} for reason in fallback_reasons],
        "page_ledger": page_ledger[:200],
        "page_failure_count": len(failed),
        "page_failure_summary": [
            {"url": page.get("discovered_url"), "reason_code": page.get("reason_code")}
            for page in failed[:20]
        ],
    }

def refresh_failure_code(exc: Exception) -> str:
    if isinstance(exc, DocsFetchSecurityError):
        return exc.category
    if isinstance(exc, httpx.ConnectTimeout):
        return "connect_timeout"
    if isinstance(exc, httpx.ReadTimeout):
        return "read_timeout"
    if isinstance(exc, httpx.TimeoutException):
        return "network_timeout"
    if isinstance(exc, httpx.ConnectError):
        return "network_unreachable"
    if isinstance(exc, httpx.TransportError):
        return "network_transport_error"
    if isinstance(exc, httpx.HTTPStatusError):
        return "http_failure"
    return "extraction_failed" if "extract" in str(exc).lower() else "indexing_failed"

def retryable_failure(exc: Exception, reason_code: str) -> bool:
    if isinstance(exc, DocsFetchSecurityError):
        return exc.retryable
    return reason_code in {
        "dns_failure", "network_unreachable", "connect_timeout", "read_timeout",
        "tls_failure", "network_timeout", "network_transport_error",
    }

def inspect_library_docs(self, canonical_id: str) -> DocsInspectResult:
        record = self.deps.registry.get(canonical_id)
        if record is None:
            return DocsInspectResult(canonical_id=canonical_id, status="missing", reason_code="missing", message="library docs target not found")
        size_bytes = self.index_size_for(record)
        pages, chunks = self.count_index_entries(record)
        manifest_expected, manifest_indexed, manifest_missing, manifest_stale_orphans, covered_manifest_digest = self.manifest_coverage(record, pages)
        active_manifest_digest = (record.target_spec or {}).get("active_manifest_digest") or covered_manifest_digest
        manifest_fetched = self.manifest_fetched(record)
        status = self.status_for(record, size_bytes)
        checkpoint = (record.target_spec or {}).get("ingestion_checkpoint") or {}
        manifest = ((record.target_spec or {}).get("source_manifest") or {})
        discovery = manifest.get("discovery") or {}
        raw_attempt_diagnostics = (record.target_spec or {}).get("last_attempt_manifest_diagnostics")
        attempt_diagnostics = (
            {
                str(key): str(value)
                for key, value in raw_attempt_diagnostics.items()
                if key in {"attempted_manifest_digest", "reason_code"}
            }
            if isinstance(raw_attempt_diagnostics, dict)
            else None
        )
        manifest_incomplete = manifest.get("schema_version") == 2 and (
            not manifest.get("complete") or bool(manifest.get("truncated"))
        )
        if manifest_expected and (manifest_missing or manifest_stale_orphans or manifest_incomplete):
            status = "corpus_incomplete"
        return DocsInspectResult(
            canonical_id=record.library_id,
            source_id=record.source_id,
            status=status,
            library=record.name,
            ecosystem=record.ecosystem,
            version=record.version,
